insert into public.recipes
  (id, name, collection, collection_label, intro, meal_types, phases, loads, dietary, serves, prep_minutes, cook_minutes, image_url, min_tier, source, calories, carbs_g, protein_g, fat_g, fibre_g, sort_order, is_active)
values
  ('mini-frittata-bites', 'Mini Frittata Bites', 'batch-and-freeze', 'Batch and freeze', 'Six of these in the fridge answer the question of what to eat after a morning session. They freeze too, so a batch on Sunday is a week of breakfasts you do not have to think about.', '{"breakfast","lunch","snack"}'::text[], '{"menstrual","follicular"}'::text[], '{"rest","easy"}'::text[], '{}'::text[], 6, 10, 20, null, null, 'virra-teamfit', 109.8, 2.2, 10.6, 6.4, 0.4, 10, true),
  ('red-lentil-vegetable-soup', 'Red Lentil & Vegetable Soup', 'batch-and-freeze', 'Batch and freeze', 'Makes six, freezes for three months, and costs very little. The kind of thing that means a bad week still has lunch in it.', '{"lunch","dinner"}'::text[], '{"menstrual","luteal"}'::text[], '{"rest","easy"}'::text[], '{"vegan","vegetarian","gf","df"}'::text[], 6, 15, 35, null, null, 'virra-authored', 237.1, 36.7, 14.0, 4.7, 7.8, 20, true),
  ('turkey-vegetable-chilli', 'Turkey & Vegetable Chilli', 'batch-and-freeze', 'Batch and freeze', 'Leaner than the beef version and every bit as good the next day. Make it on a Sunday and Wednesday looks after itself.', '{"lunch","dinner"}'::text[], '{"menstrual","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"gf","df"}'::text[], 4, 15, 35, null, null, 'virra-authored', 383.5, 27.2, 33.9, 16.2, 7.2, 30, true),
  ('sweet-potato-black-bean-chilli', 'Sweet Potato & Black Bean Chilli', 'batch-and-freeze', 'Batch and freeze', 'The vegan one that nobody feels short-changed by. Sweet potato gives it body, and the carbohydrate makes it a proper post-session dinner rather than a side.', '{"lunch","dinner"}'::text[], '{"luteal","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"vegan","vegetarian","gf","df"}'::text[], 4, 15, 35, null, null, 'virra-authored', 348.0, 61.3, 12.5, 7.2, 14.6, 40, true),
  ('biscoff-overnight-oats', 'Biscoff Overnight Oats', 'breakfast', 'Breakfast', 'Made the night before, eaten cold, sweet enough to feel like a treat, and carrying nearly thirty grams of protein. The kind of breakfast that makes an early alarm easier.', '{"breakfast","snack"}'::text[], '{"follicular","luteal"}'::text[], '{"easy","moderate"}'::text[], '{"vegetarian"}'::text[], 1, 5, 0, null, null, 'virra-teamfit', 414.1, 44.4, 27.6, 13.2, 4.4, 10, true),
  ('smoked-salmon-scrambled-eggs', 'Smoked Salmon Scrambled Eggs', 'breakfast', 'Breakfast', 'The breakfast to make when you want the day to start well rather than just start. Thirty grams of protein before you have properly woken up.', '{"breakfast"}'::text[], '{"follicular","ovulatory"}'::text[], '{"easy","moderate"}'::text[], '{"pescatarian"}'::text[], 1, 5, 8, null, null, 'virra-authored', 458.9, 32.9, 30.6, 21.9, 1.6, 20, true),
  ('banana-peanut-porridge', 'Banana & Peanut Butter Porridge', 'breakfast', 'Breakfast', 'Warm, sweet and genuinely filling, with enough carbohydrate behind it to hold up a hard morning. The peanut butter is not optional.', '{"breakfast"}'::text[], '{"ovulatory","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"vegetarian"}'::text[], 1, 2, 6, null, null, 'virra-authored', 596.2, 80.4, 21.2, 20.2, 8.7, 30, true),
  ('greek-yogurt-berry-bowl', 'Greek Yogurt & Berry Bowl', 'breakfast', 'Breakfast', 'Five minutes, no cooking, and a lot of protein for something that feels like a treat. The one to make when the morning is already busy.', '{"breakfast","snack"}'::text[], '{"follicular"}'::text[], '{"rest","easy"}'::text[], '{"vegetarian"}'::text[], 1, 5, 0, null, null, 'virra-authored', 416.6, 55.3, 26.9, 10.6, 7.6, 40, true),
  ('mushroom-spinach-omelette', 'Mushroom & Spinach Omelette', 'breakfast', 'Breakfast', 'Iron from the spinach and the yolks, protein to spare, and it is on the plate in under fifteen minutes. A good one for the days you need feeding rather than fuelling.', '{"breakfast","lunch"}'::text[], '{"menstrual","follicular"}'::text[], '{"rest","easy"}'::text[], '{"vegetarian","gf"}'::text[], 1, 5, 8, null, null, 'virra-authored', 391.6, 2.1, 26.5, 30.3, 1.6, 50, true),
  ('mexican-tray-bake', 'Mexican Tray Bake', 'dinner', 'Dinner', 'This super simple veggie tray bake is packed full of Mexican flavours! Coat sweet potato, pepper, cherry tomatoes and black beans in smoky seasonings and roast. Top with Greek cheese and chipotle yoghurt.', '{"lunch","dinner"}'::text[], '{"menstrual","luteal"}'::text[], '{"rest","easy","moderate"}'::text[], '{"vegetarian","gf"}'::text[], 2, 10, 30, null, null, 'virra-authored', 425.0, 51.0, 22.0, 14.0, 17.0, 0, true),
  ('chipotle-chicken', 'Chipotle Chicken', 'dinner', 'Dinner', 'A Mexican-inspired dish that pairs smoky pulled chicken with fluffy white rice and a tangy tomato salsa - the perfect pairing to a rest day evening, recovery from training.', '{"dinner"}'::text[], '{"luteal"}'::text[], '{"rest","easy"}'::text[], '{"gf","df"}'::text[], 2, 10, 25, null, null, 'virra-authored', 539.0, 71.0, 35.0, 15.0, 6.0, 10, true),
  ('fruity-cous-cous', 'Fruity Cous Cous', 'lunch', 'Lunch', 'Ten minutes, nothing hotter than a kettle, and it travels well. Carbs and something bright for the days when lunch has to happen between other things.', '{"lunch","dinner"}'::text[], '{"menstrual","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"vegan","vegetarian","df"}'::text[], 2, 10, 0, null, null, 'virra-teamfit', 410.6, 67.9, 11.5, 10.9, 6.2, 10, true),
  ('race-morning-bagel', 'Race Morning Bagel', 'pre-run', 'Pre-run and race morning', 'Deliberately dull, and that is the point. Low fibre, low fat, plenty of carbohydrate, and nothing in it your stomach has to think about two hours before a start line.', '{"breakfast"}'::text[], '{"ovulatory","luteal"}'::text[], '{"hard"}'::text[], '{"vegan","vegetarian","df"}'::text[], 1, 3, 0, null, null, 'virra-authored', 413.1, 78.1, 12.2, 6.7, 3.6, 20, true),
  ('honey-banana-toast', 'Honey & Banana Toast', 'pre-run', 'Pre-run and race morning', 'The simplest thing in the book. White bread on purpose, because an hour before a session is not the moment for fibre.', '{"breakfast","snack"}'::text[], '{"ovulatory","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"vegetarian","df"}'::text[], 1, 3, 2, null, null, 'virra-authored', 350.0, 79.3, 7.6, 1.7, 3.1, 30, true),
  ('pre-run-smoothie', 'Pre-Run Smoothie', 'pre-run', 'Pre-run and race morning', 'For the mornings when eating feels like hard work but you still have to fuel. Drinkable carbohydrate, and gentler on a nervous stomach than a plate of anything.', '{"breakfast","snack"}'::text[], '{"ovulatory","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"vegetarian","df"}'::text[], 1, 5, 0, null, null, 'virra-authored', 382.5, 77.9, 6.4, 5.1, 5.2, 40, true),
  ('pineapple-yogurt-pot', 'Pineapple & Yogurt Pot', 'pre-run', 'Pre-run and race morning', 'Light enough to sit well before a session, with enough protein to still be doing something for you afterwards. Make it the night before and it travels.', '{"breakfast","snack"}'::text[], '{"follicular","ovulatory"}'::text[], '{"easy","moderate"}'::text[], '{"vegetarian","gf"}'::text[], 1, 5, 0, null, null, 'virra-authored', 281.3, 47.2, 17.2, 3.3, 2.7, 50, true),
  ('prawn-pineapple-stir-fry', 'Prawn & Pineapple Stir-Fry', 'quick-dinners', 'Quick dinners', 'On the table in twenty-five minutes, and the juice from the pineapple tin does the work of a shop-bought sauce. A good one the evening before a long run.', '{"lunch","dinner"}'::text[], '{"ovulatory","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"pescatarian","df"}'::text[], 2, 10, 15, null, null, 'virra-teamfit', 505.6, 71.0, 23.9, 13.5, 4.8, 10, true),
  ('lemon-chicken-new-potatoes', 'Lemon Chicken & New Potatoes', 'quick-dinners', 'Quick dinners', 'One tray, one lemon, and very little washing up. The potatoes go in first so they are properly crisp by the time the chicken is done.', '{"lunch","dinner"}'::text[], '{"follicular","ovulatory"}'::text[], '{"moderate"}'::text[], '{"gf"}'::text[], 2, 10, 25, null, null, 'virra-authored', 423.5, 37.0, 39.4, 13.8, 6.4, 20, true),
  ('salmon-sweet-potato-broccoli', 'Salmon, Sweet Potato & Broccoli', 'quick-dinners', 'Quick dinners', 'The dinner that quietly does everything: oily fish, a proper amount of carbohydrate, and something green. Good the night before a long run.', '{"dinner"}'::text[], '{"follicular","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"pescatarian","gf","df"}'::text[], 2, 10, 25, null, null, 'virra-authored', 586.3, 45.1, 34.6, 30.8, 8.7, 30, true),
  ('beef-black-bean-rice', 'Beef & Black Bean Rice', 'quick-dinners', 'Quick dinners', 'Iron from the beef and the beans in one bowl, which makes it a good one when you are heavy or tired. It reheats well, so make the full three.', '{"dinner"}'::text[], '{"menstrual","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"gf","df"}'::text[], 3, 10, 25, null, null, 'virra-authored', 487.0, 61.2, 32.3, 11.7, 8.5, 40, true),
  ('tuna-pasta-with-passata', 'Tuna Pasta', 'quick-dinners', 'Quick dinners', 'Store cupboard, fifteen minutes, and better than it has any right to be. The parmesan at the end is what lifts it.', '{"lunch","dinner"}'::text[], '{"ovulatory","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"pescatarian"}'::text[], 2, 5, 15, null, null, 'virra-authored', 603.4, 67.4, 47.3, 15.2, 10.0, 50, true),
  ('chickpea-spinach-curry', 'Chickpea & Spinach Curry', 'quick-dinners', 'Quick dinners', 'Iron from the chickpeas and the spinach, and a squeeze of lemon at the end to help you actually absorb it. Cheap, fast and better on day two.', '{"lunch","dinner"}'::text[], '{"menstrual","luteal"}'::text[], '{"moderate"}'::text[], '{"vegan","vegetarian","gf","df"}'::text[], 2, 10, 20, null, null, 'virra-authored', 546.8, 88.5, 18.5, 12.9, 12.4, 60, true),
  ('sausage-ragu', 'Sausage Ragu', 'quick-dinners', 'Quick dinners', 'A traditional, Sardinian-inspired ragù recipe that is rich, velvety and has just a touch of ''zestyness'' thanks to the ground paprika! Add some garlic bread for the perfect carb-load or re-fuel after a long run.', '{"dinner"}'::text[], '{"follicular"}'::text[], '{"hard"}'::text[], '{}'::text[], 2, 10, 10, null, null, 'virra-authored', 747.0, 83.0, 36.0, 29.0, 6.0, 70, true),
  ('chicken-quinoa-bowl', 'Chicken & Quinoa Bowl', 'recovery', 'Recovery and high-protein', 'Built for the hour after a hard session: a lot of protein, a proper amount of carbohydrate, and it is just as good cold the next day.', '{"lunch","dinner"}'::text[], '{"follicular","ovulatory"}'::text[], '{"moderate","hard"}'::text[], '{"gf","df"}'::text[], 2, 10, 20, null, null, 'virra-authored', 614.8, 55.8, 50.5, 20.7, 9.9, 10, true),
  ('cottage-cheese-recovery-pot', 'Cottage Cheese Recovery Pot', 'recovery', 'Recovery and high-protein', 'Not glamorous, extremely effective. Thirty grams of protein in something you can put together in the kitchen with your shoes still on.', '{"snack","breakfast"}'::text[], '{"follicular"}'::text[], '{"easy","moderate"}'::text[], '{"vegetarian","gf"}'::text[], 1, 5, 0, null, null, 'virra-authored', 479.2, 51.2, 31.4, 16.9, 5.8, 20, true),
  ('tofu-edamame-noodles', 'Tofu & Edamame Noodles', 'recovery', 'Recovery and high-protein', 'Plant protein that actually adds up, and it comes together in the time the noodles take. Press the tofu if you have ten minutes spare, it makes all the difference.', '{"lunch","dinner"}'::text[], '{"follicular","luteal"}'::text[], '{"moderate","hard"}'::text[], '{"vegan","vegetarian","df"}'::text[], 2, 10, 15, null, null, 'virra-authored', 538.5, 64.0, 24.6, 20.1, 8.0, 30, true),
  ('protein-recovery-shake', 'Protein Recovery Shake', 'recovery', 'Recovery and high-protein', 'For the twenty minutes after a hard session when you are not hungry yet but should be eating something. Carbohydrate and protein together, in a form you can drink.', '{"snack"}'::text[], '{"ovulatory","luteal"}'::text[], '{"hard"}'::text[], '{"vegetarian","gf"}'::text[], 1, 3, 0, null, null, 'virra-authored', 527.2, 52.8, 38.9, 17.3, 3.9, 40, true),
  ('mackerel-green-lentils', 'Mackerel with Green Lentils', 'recovery', 'Recovery and high-protein', 'Oily fish and lentils, which between them cover protein, iron and omega-3 in one pan. The lemon is doing real work here, not just brightening it.', '{"lunch","dinner"}'::text[], '{"menstrual","follicular"}'::text[], '{"easy","moderate"}'::text[], '{"pescatarian","gf","df"}'::text[], 2, 10, 20, null, null, 'virra-authored', 448.5, 23.1, 30.9, 26.3, 6.5, 50, true);
