insert into public.recipe_steps
  (recipe_id, position, body, timer_seconds)
values
  ('banana-peanut-porridge', 1, 'Put the oats and milk in a pan over a medium heat.', null),
  ('banana-peanut-porridge', 2, 'Stir often and let it bubble gently for 5 to 6 minutes, until it thickens and the oats soften.', null),
  ('banana-peanut-porridge', 3, 'Take it off the heat and stir through half the banana so it melts into the porridge.', null),
  ('banana-peanut-porridge', 4, 'Pour into a bowl, top with the rest of the banana, the peanut butter and the honey.', null),
  ('banana-peanut-porridge', 5, 'Scatter the chia seeds over if you are using them, and let it sit for a minute before eating.', null),
  ('beef-black-bean-rice', 1, 'Get the rice on first, cooked to the packet timing.', null),
  ('beef-black-bean-rice', 2, 'Heat the oil in a wide pan and brown the mince properly, breaking it up as you go. Give it a few minutes without stirring at the start so it colours rather than steams.', null),
  ('beef-black-bean-rice', 3, 'Add the onion and pepper and cook for 5 minutes until softened.', null),
  ('beef-black-bean-rice', 4, 'Stir in the garlic, cumin and chilli flakes and cook for another minute, until you can smell them.', null),
  ('beef-black-bean-rice', 5, 'Add the tomatoes and the drained beans, season, and simmer for 10 minutes.', null),
  ('beef-black-bean-rice', 6, 'Serve over the rice.', null),
  ('biscoff-overnight-oats', 1, 'Mix together your oats, milk, yoghurt and protein powder until the mixture is smooth. Any flavour works, but vanilla is best for this.', null),
  ('biscoff-overnight-oats', 2, 'Melt the Biscoff spread, either microwaved for 20 seconds or with a little boiling water. Stir until silky.', null),
  ('biscoff-overnight-oats', 3, 'Pop your mixture in a Kilner jar, or any bowl you can cover, and top with the melted spread.', null),
  ('biscoff-overnight-oats', 4, 'Crumble your Biscoff biscuit over the top, or be an animal and dunk it.', null),
  ('biscoff-overnight-oats', 5, 'Leave overnight and enjoy.', null),
  ('chicken-quinoa-bowl', 1, 'Rinse the quinoa well, then cook it in twice its volume of water for about 15 minutes, until the grains uncurl.', null),
  ('chicken-quinoa-bowl', 2, 'Season the chicken and cook it in half the oil over a medium heat, 6 to 7 minutes a side depending on thickness. Let it rest before slicing.', null),
  ('chicken-quinoa-bowl', 3, 'Steam the broccoli for 4 minutes and slice the pepper raw for crunch.', null),
  ('chicken-quinoa-bowl', 4, 'Fork the remaining oil and the lemon juice through the quinoa and season it properly. Quinoa needs more salt than you think.', null),
  ('chicken-quinoa-bowl', 5, 'Build the bowls with the quinoa underneath, then the vegetables and the sliced chicken.', null),
  ('chicken-quinoa-bowl', 6, 'Scatter the pumpkin seeds over the top.', null),
  ('chickpea-spinach-curry', 1, 'Start the rice so it is ready when the curry is.', null),
  ('chickpea-spinach-curry', 2, 'Heat the oil and cook the onion for 6 to 7 minutes until soft and just golden.', null),
  ('chickpea-spinach-curry', 3, 'Add the garlic, ginger and curry powder and stir for a minute. This step is what stops it tasting raw.', null),
  ('chickpea-spinach-curry', 4, 'Tip in the tomatoes and chickpeas, season, and simmer for 10 minutes.', null),
  ('chickpea-spinach-curry', 5, 'Stir the spinach through in handfuls until it wilts.', null),
  ('chickpea-spinach-curry', 6, 'Squeeze the lemon in off the heat, scatter the coriander, and serve with the rice.', null),
  ('chipotle-chicken', 1, 'Add your long grain rice to a pan with a lid with 225ml cold water and a pinch of salt and bring to the boil over a high heat. Once boiling, reduce the heat to very low and cook, covered, for 12-15 min or until all the water has absorbed and the rice is cooked. (Once done, remove from the heat and set aside (lid on) to steam until serving.)', null),
  ('chipotle-chicken', 2, 'Zest your lime and then peel and finely chop (or grate) your garlic. Keep your lime to hand for later as you will need the juice!
